import{_ as t,o as r,c as a,a4 as s}from"./chunks/framework.FL_xemTS.js";const h=JSON.parse('{"title":"Experimental Plugin Record Catalog","description":"","frontmatter":{"editSource":"docs/experimental-persistence-catalog.md","rawMarkdownPath":"en/reference/experimental-persistence-catalog.md"},"headers":[],"relativePath":"en/reference/experimental-persistence-catalog.md","filePath":"en/reference/experimental-persistence-catalog.md"}'),o={name:"en/reference/experimental-persistence-catalog.md"};function d(n,e,c,i,p,l){return r(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="experimental-plugin-record-catalog" tabindex="-1">Experimental Plugin Record Catalog <a class="header-anchor" href="#experimental-plugin-record-catalog" aria-label="Permalink to &quot;Experimental Plugin Record Catalog&quot;">​</a></h1><p>These current-source PluginRecordMap declarations describe ignorable, log-only records owned by experimental packages. Payload annotations link to their owning source without expanding referenced types. Records stay outside the known-event set, persistence schema fingerprints, and compatibility history; format migrations retain them on a best-effort basis.</p><p>Run <code>pnpm run gen-persistence-catalog</code> to regenerate both persistence catalogs, their language pairs, and associated artifacts. <code>pnpm run verify-persistence-catalog</code> checks all generated files.</p><p>Shared Session event declarations and resolved schemas appear in the <a href="./persistence-catalog">Session persistence event catalog</a>.</p><table tabindex="0"><thead><tr><th>Record</th><th>Owner</th><th>Purpose</th><th>Payload and source</th></tr></thead><tbody><tr><td><code>plugin:action-cards/decision</code></td><td><code>@deepseek-ai/dsh-action-cards</code></td><td>Dismissals and kind-defined progress of action cards.</td><td><code>ActionCardDecision</code> · <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/packages/experimental/action-cards/src/types.ts" target="_blank" rel="noreferrer"><code>packages/experimental/action-cards/src/types.ts</code></a></td></tr><tr><td><code>plugin:client-ui-forge/worktree</code></td><td><code>@deepseek-ai/dsh-experimental-client-ui-forge</code></td><td>A request, withdrawal, or creation of the worktree a Session starts in.</td><td><code>WorktreeRecord</code> · <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/packages/experimental/client-ui-forge/src/types.ts" target="_blank" rel="noreferrer"><code>packages/experimental/client-ui-forge/src/types.ts</code></a></td></tr><tr><td><code>plugin:forge-session/binding</code></td><td><code>@deepseek-ai/dsh-experimental-forge-session</code></td><td>A caller or discovery action that binds, restores, or hides one change request.</td><td><code>BindingRecord</code> · <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/packages/experimental/forge-session/src/types.ts" target="_blank" rel="noreferrer"><code>packages/experimental/forge-session/src/types.ts</code></a></td></tr><tr><td><code>plugin:translator/request</code></td><td><code>@deepseek-ai/dsh-experimental-translator</code></td><td>Provider-independent translation input, retained before dispatch.</td><td><code>TranslationRequestRecord</code> · <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/packages/experimental/translator/src/types.ts" target="_blank" rel="noreferrer"><code>packages/experimental/translator/src/types.ts</code></a></td></tr><tr><td><code>plugin:translator/result</code></td><td><code>@deepseek-ai/dsh-experimental-translator</code></td><td>Successful translation, retained before it is returned to the consumer.</td><td><code>TranslationResultRecord</code> · <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/packages/experimental/translator/src/types.ts" target="_blank" rel="noreferrer"><code>packages/experimental/translator/src/types.ts</code></a></td></tr><tr><td><code>plugin:worktree/created</code></td><td><code>@deepseek-ai/dsh-experimental-worktree</code></td><td>A checkout the worktree service created for the Session, which entered it in the same operation.</td><td><code>CreatedWorktree</code> · <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/packages/experimental/worktree/src/projection.ts" target="_blank" rel="noreferrer"><code>packages/experimental/worktree/src/projection.ts</code></a></td></tr></tbody></table>',5)])])}const m=t(o,[["render",d]]);export{h as __pageData,m as default};
